mapper.select:
select order_id,return_code,shop_name,shop_id,intervention_state,application_time,return_state,return_method_type,expriation_time
FROM ${database.prefix.order}hou_order_return_platform where  1 = 1 and intervention_state != 0

    and return_code = #{param.returnCode}


    and order_id = #{param.orderId}


    and shop_name like  CONCAT('%',#{param.shopName },'%')


    and intervention_state = #{param.interventionState}


    and  application_time between #{param.startTime} and #{param.endTime}


     and now() <= expriation_time 


    and now() >= expriation_time

order by application_time  desc

select seller_user_id, buyer_user_id
FROM ${database.prefix.order}hou_order_return
where return_code = #{returnCode}
